export interface DataModelTable {
  table_name: string;
  description: string;
  hub_refs: string[];
  row_estimate: number;
  has_rls: boolean;
  category: string;
  key_columns: string[];
  relations: { foreign_table: string; relationship: string }[];
}

export interface DataDomainSummary {
  domain_id: string;
  domain_name: string;
  description: string;
  table_count: number;
  total_rows_estimate: number;
  icon: string;
  color: string;
  hub_refs: string[];
  standards: string[];
  tables: DataModelTable[];
}

export interface RelationalSchemaLink {
  from_table: string;
  from_domain: string;
  to_table: string;
  to_domain: string;
  relationship: string;
  cardinality: '1:1' | '1:N' | 'N:M';
}

export interface DataGovernanceRule {
  rule_id: string;
  rule_name: string;
  category: 'naming' | 'security' | 'quality' | 'lifecycle' | 'audit' | 'performance';
  description: string;
  standard_ref: string;
  compliance: 'compliant' | 'partial' | 'non_compliant';
  affected_tables_count: number;
}

export interface DataQualityMetric {
  metric_name: string;
  current_value: number;
  target_value: number;
  unit: string;
  trend: 'up' | 'down' | 'stable';
  domain: string;
  last_checked: string;
}

export interface ValidationWorkflow {
  step: number;
  step_name: string;
  description: string;
  responsible: string;
  tool: string;
  frequency: string;
  status: 'active' | 'pending' | 'draft';
}

export interface EnterpriseDataModel {
  bloc_id: string;
  bloc_name: string;
  version: string;
  executive_summary: string;
  total_tables: number;
  total_rows_estimate: number;
  domains: number;
  certification_target: string;
  current_maturity: number;
  target_maturity: number;
  standards: string[];
  domains_summary: DataDomainSummary[];
  relational_schema: RelationalSchemaLink[];
  governance_rules: DataGovernanceRule[];
  quality_metrics: DataQualityMetric[];
  validation_workflow: ValidationWorkflow[];
}

